create_user.beforeRequest:
const body = request.body;
body.userType = body.userType || 'EPVUser';
if (inputs.expiryDate) body.expiryDate = Math.floor(new Date(inputs.expiryDate).getTime() / 1000);
for (const group of ['personalDetails', 'internet', 'phones', 'businessAddress']) if (Object.keys(body[group]).length === 0) delete body[group];
return request;

update_user.beforeRequest:
const body = request.body;
const seconds = (value) => Math.floor(new Date(value).getTime() / 1000);
body.id = parseInt(inputs.userId);
body.userType = body.userType || 'EPVUser';
body.location = body.location || '\\\\';
for (const field of ['expiryDate', 'loginFromHour', 'loginToHour']) if (inputs[field]) body[field] = seconds(inputs[field]);
if (inputs.authenticationMethod) body.authenticationMethod = [inputs.authenticationMethod];
for (const group of ['personalDetails', 'internet', 'phones', 'businessAddress']) if (Object.keys(body[group]).length === 0) delete body[group];
return request;

find_user.beforeRequest:
const query = request.query;
if (query.ExtendedDetails !== 'true') delete query.ExtendedDetails;
for (const key of ['pageOffset', 'pageSize']) if (!(Number(query[key]) > 0)) delete query[key];
// The original writes the query as a form does, with + for a space, and gives that address back as queryUsed.
const encode = (value) => encodeURIComponent(value).replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
const search = Object.entries(query).map(([key, value]) => `${encode(key)}=${encode(value)}`).join('&');
if (search) request.url += `?${search}`;
request.query = {};
return request;

find_user.afterResponse:
const decode = (part) => decodeURIComponent(part.replace(/\+/g, ' '));
const parameters = Object.fromEntries((request.url.split('?')[1] || '').split('&').filter(Boolean).map((pair) => pair.split('=').map(decode)));
return { success: true, users: response.Users || [], total: response.Total || 0, queryUsed: { url: request.url, parameters } };
